/bin/bash -lc "python - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png'))
Y=im.mean(2)
for y in range(45,126,3):
 print(f'{y:3}:',end=' ')
 for t in [35,55,75]:
  z=np.where(Y[y]<t)[0]; runs=[]
  if len(z):
   a=p=z[0]
   for q in z[1:]:
    if q>p+1:
     if p-a>=2:runs.append((a,p))
     a=q
    p=q
   if p-a>=2:runs.append((a,p))
  print(t,runs,end='; ')
 print()
# Samples RGB per selected rows 90-180 every 5 x
for y in [55,58,60,64,68,72,80,90,98,105,115,120,125]:
 print('\\ny',y)
 for x in range(90,181,5): print(x,tuple(im[y,x]),end=' ') 
